import java.util.ArrayList;
import java.util.List;
import java.util.ListIterator;

public class ListIteratorDemo {
    public static void main(String[] args) {
        List<String> script = new ArrayList<>();
        script.add("init");
        script.add("connect");
        script.add("poll");
        script.add("teardown");

        ListIterator<String> it = script.listIterator();

        // 1. Forward traversal with in-place replacement (set)
        while (it.hasNext()) {
            String step = it.next();
            if (step.equals("poll")) {
                it.set("stream_data"); // In-flight replacement!
                it.add("flush_buffer"); // In-flight insertion!
            }
        }
        System.out.println("After modification: " + script);

        // 2. Backward traversal from end of list
        System.out.print("Reverse traversal:  ");
        while (it.hasPrevious()) {
            System.out.print(it.previous() + " <- ");
        }
        System.out.println("START");
    }
}
// Expected Output:
// After modification: [init, connect, stream_data, flush_buffer, teardown]
// Reverse traversal:  teardown <- flush_buffer <- stream_data <- connect <- init <- START

