import java.util.List;
import java.util.ListIterator;
import java.util.Objects;

public class ListPalindromeChecker {
    public static <T> boolean isPalindrome(List<T> list) {
        if (list == null || list.size() <= 1) return true;
        ListIterator<T> forward = list.listIterator();
        ListIterator<T> backward = list.listIterator(list.size());

        while (forward.nextIndex() < backward.previousIndex()) {
            T head = forward.next();
            T tail = backward.previous();
            if (!Objects.equals(head, tail)) {
                return false;
            }
        }
        return true;
    }

    public static void main(String[] args) {
        List<String> radar = List.of("R", "A", "D", "A", "R");
        List<String> code = List.of("J", "A", "V", "A");

        System.out.println("Is RADAR a palindrome? " + isPalindrome(radar)); // true
        System.out.println("Is JAVA a palindrome?  " + isPalindrome(code));  // false
    }
}

