import java.util.List;
import java.util.ArrayList;
import java.util.ListIterator;
import java.util.Objects;

public class WordReplacer {
    public static void replaceAllOccurrences(List<String> list, String target, String replacement) {
        if (list == null) return;
        ListIterator<String> it = list.listIterator();
        while (it.hasNext()) {
            if (Objects.equals(it.next(), target)) {
                it.set(replacement);
            }
        }
    }

    public static void main(String[] args) {
        List<String> words = new ArrayList<>(List.of("cat", "dog", "cat", "bird"));
        replaceAllOccurrences(words, "cat", "lion");
        System.out.println(words);
    }
}

