import java.util.List;
import java.util.ArrayList;
import java.util.ListIterator;

public class DelimiterInterleaver {
    public static void interleaveDelimiter(List<String> list, String delimiter) {
        if (list == null || list.size() <= 1) return;
        ListIterator<String> it = list.listIterator();
        if (it.hasNext()) it.next(); // skip first item
        while (it.hasNext()) {
            it.previous();
            it.add(delimiter);
            it.next(); // skip delimiter
            it.next(); // skip original next element
        }
    }

    public static void main(String[] args) {
        List<String> tokens = new ArrayList<>(List.of("A", "B", "C"));
        interleaveDelimiter(tokens, "-");
        System.out.println(tokens);
    }
}

